package android.graphics;public class Typeface {public static final int NORMAL=0,BOLD=1;public final String family;public final int weight;public final boolean italic;public Typeface(String family,int weight,boolean italic){this.family=family;this.weight=weight;this.italic=italic;}public static Typeface create(String family,int style){return new Typeface(family,style==BOLD?700:400,false);}public static Typeface create(Typeface family,int weight,boolean italic){return new Typeface(family==null?"sans-serif":family.family,weight,italic);}}
